#include "tkl_i2s.h"
#include "tuya_error_code.h"
#include <ti/drivers/I2S.h>

// [DEPENDENCY INJECTION] Include Board Config
#include "tkl_board_config.h"

// Check if I2S max ports is defined, otherwise default to 1 (Typical for MCU)
#ifndef TKL_BOAD_MAX_I2S_PORTS
#define TKL_BOAD_MAX_I2S_PORTS 1
#endif

// Global array to store handles
static I2S_Handle g_i2s_handles[TKL_BOAD_MAX_I2S_PORTS] = {NULL};

// Helper to check validity
static bool is_valid_port(TUYA_I2S_NUM_E port) {
    return (port < TKL_BOAD_MAX_I2S_PORTS);
}
// --- END: user defines and implements ---

/**
 * @brief tuya i2s init
 *
 * @param[in] i2s_num: i2s port number
 * @param[in] i2s_config: i2s config
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */

OPERATE_RET tkl_i2s_init(TUYA_I2S_NUM_E i2s_num, const TUYA_I2S_BASE_CFG_T *i2s_config)
{
    // --- BEGIN: user implements ---
    if (!is_valid_port(i2s_num) || i2s_config == NULL) {
        return OPRT_INVALID_PARM;
    }

    // [MAPPING] Look up TI index dynamically
    // Note: Ensure tkl_hw_get_i2s_index is defined in your tkl_board.c
    int16_t ti_i2s_index = tkl_hw_get_i2s_index((uint8_t)i2s_num);

    // If result is negative, the Application did not map this I2S port.
    if (ti_i2s_index < 0) {
        return OPRT_NOT_SUPPORTED;
    }

    // Close existing if open
    if (g_i2s_handles[i2s_num] != NULL) {
        I2S_close(g_i2s_handles[i2s_num]);
        g_i2s_handles[i2s_num] = NULL;
    }

    I2S_init();

    I2S_Params params;
    I2S_Params_init(&params);

    // Map Configuration
    // 1. Mode (Master/Slave)
    if (i2s_config->mode == TUYA_I2S_MODE_MASTER) {
        params.moduleRole = I2S_CONTROLLER;
    } else {
        params.moduleRole = I2S_TARGET;
    }

    // 2. Sampling Rate
    params.samplingFrequency = i2s_config->sample_rate;

    // 3. Data Width (Bits per sample)
    params.bitsPerWord = i2s_config->bits_per_sample;

    // 4. Channels (Mono/Stereo)
    // TI Driver handles channels differently (via phase types), assuming Stereo/Dual Phase standard
    if (i2s_config->channel_format == 1) {
        params.phaseType = I2S_PHASE_TYPE_SINGLE; 
    } else {
        params.phaseType = I2S_PHASE_TYPE_DUAL; // Stereo
    }

    // Open using Mapped Index
    g_i2s_handles[i2s_num] = I2S_open(ti_i2s_index, &params);

    if (g_i2s_handles[i2s_num] == NULL) {
        return OPRT_COM_ERROR;
    }

    return OPRT_OK;
    // --- END: user implements ---
}

/**
 * @brief tuya i2s send
 *
 * @param[in] i2s_num: i2s port number
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */

OPERATE_RET tkl_i2s_send(TUYA_I2S_NUM_E i2s_num, void *buff, uint32_t len)
{
    // --- BEGIN: user implements ---
    if (!is_valid_port(i2s_num) || g_i2s_handles[i2s_num] == NULL) {
        return OPRT_NOT_SUPPORTED;
    }
    
    // Note: TI I2S requires queuing I2S_Transaction structures.
    // A simple blocking 'send' is not natively supported without a wrapper queue.
    // Returning NOT_SUPPORTED until a transaction queue is implemented.
    return OPRT_NOT_SUPPORTED;
    // --- END: user implements ---
}

