/**
 * @brief tuya i2s deinit
 *
 * @param[in] i2s_num: i2s port number
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */

OPERATE_RET tkl_i2s_deinit(TUYA_I2S_NUM_E i2s_num)
{
    // --- BEGIN: user implements ---
    if (!is_valid_port(i2s_num)) {
        return OPRT_INVALID_PARM;
    }

    if (g_i2s_handles[i2s_num] != NULL) {
        // Stop any ongoing transfers
        I2S_stopRead(g_i2s_handles[i2s_num]);
        I2S_stopWrite(g_i2s_handles[i2s_num]);
        
        I2S_close(g_i2s_handles[i2s_num]);
        g_i2s_handles[i2s_num] = NULL;
    }

    return OPRT_OK;
    // --- END: user implements ---
}